-- The whole schema as of migration 20261115T1557_init, for a database that is
-- still empty and that the GitHub workflows cannot reach yet.
--
-- These are the statements that `npm run db:migrate` followed by
-- `npm run db:bootstrap` send to an empty database, recorded from a run against
-- a local PostgreSQL and replayed here unchanged: Prisma's tables in
-- "prisma_contract" (with the marker, so that `prisma db migrate` afterwards
-- reports "no operations"), the app's 34 tables in "public", their indexes,
-- constraints, the two counter triggers.
--
-- Run it once, as the role the app connects with, inside one transaction, on a
-- database with no tables in "public". It is not re-runnable. Later migrations
-- are applied on top by `npm run db:migrate` in the usual way.
--
-- On Supabase, run prisma/supabase-lockdown.sql first, so the new tables are
-- not granted to the Data API roles. See DATABASE.md, "Using Supabase".

CREATE SCHEMA IF NOT EXISTS "prisma_contract";
CREATE TABLE IF NOT EXISTS "prisma_contract"."marker" (
  "space" text DEFAULT 'app' NOT NULL PRIMARY KEY,
  "core_hash" text NOT NULL,
  "profile_hash" text NOT NULL,
  "contract_json" jsonb,
  "canonical_version" int,
  "updated_at" timestamptz DEFAULT (now()) NOT NULL,
  "app_tag" text,
  "meta" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "invariants" text[] DEFAULT '{}'::text[] NOT NULL
);
CREATE TABLE IF NOT EXISTS "prisma_contract"."ledger" (
  "id" bigserial PRIMARY KEY,
  "created_at" timestamptz DEFAULT (now()) NOT NULL,
  "space" text NOT NULL,
  "migration_name" text NOT NULL,
  "migration_hash" text NOT NULL,
  "origin_core_hash" text,
  "origin_profile_hash" text,
  "destination_core_hash" text NOT NULL,
  "destination_profile_hash" text,
  "operations" jsonb NOT NULL
);
CREATE TABLE IF NOT EXISTS "prisma_contract"."contract" (
  "core_hash" text NOT NULL PRIMARY KEY,
  "created_at" timestamptz DEFAULT (now()) NOT NULL,
  "contract_json" jsonb NOT NULL
);
CREATE SCHEMA IF NOT EXISTS "public";
CREATE TABLE "public"."accounts" (
  "access_token" text,
  "expires_at" int4,
  "id" SERIAL NOT NULL,
  "id_token" text,
  "provider" text NOT NULL,
  "provider_account_id" text NOT NULL,
  "refresh_token" text,
  "scope" text,
  "token_type" text,
  "type" text NOT NULL,
  "user_id" int4 NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE "public"."blocks" (
  "blocked_id" int4 NOT NULL,
  "blocker_id" int4 NOT NULL,
  "created_at" timestamp(6) DEFAULT (now()) NOT NULL,
  PRIMARY KEY ("blocker_id", "blocked_id")
);
CREATE TABLE "public"."bookmarks" (
  "created_at" timestamp(6) DEFAULT (now()) NOT NULL,
  "id" SERIAL NOT NULL,
  "post_id" int4 NOT NULL,
  "user_id" int4 NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE "public"."comments" (
  "content" text NOT NULL,
  "created_at" timestamp(6) DEFAULT (now()) NOT NULL,
  "id" SERIAL NOT NULL,
  "post_id" int4 NOT NULL,
  "user_id" int4 NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE "public"."follow_requests" (
  "created_at" timestamp(6) DEFAULT (now()) NOT NULL,
  "follower_id" int4 NOT NULL,
  "following_id" int4 NOT NULL,
  "id" SERIAL NOT NULL,
  "status" text DEFAULT 'pending' NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE "public"."follows" (
  "created_at" timestamp(6) DEFAULT (now()) NOT NULL,
  "follower_id" int4 NOT NULL,
  "following_id" int4 NOT NULL,
  PRIMARY KEY ("follower_id", "following_id")
);
CREATE TABLE "public"."group_calls" (
  "created_at" timestamp(6) DEFAULT (now()) NOT NULL,
  "creator_id" int4 NOT NULL,
  "description" text,
  "group_id" int4 NOT NULL,
  "id" SERIAL NOT NULL,
  "is_active" bool DEFAULT true NOT NULL,
  "room_url" text NOT NULL,
  "title" text NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE "public"."group_event_rsvps" (
  "created_at" timestamp(6) DEFAULT (now()) NOT NULL,
  "event_id" int4 NOT NULL,
  "status" text DEFAULT 'going' NOT NULL,
  "user_id" int4 NOT NULL,
  PRIMARY KEY ("event_id", "user_id")
);
CREATE TABLE "public"."group_events" (
  "created_at" timestamp(6) DEFAULT (now()) NOT NULL,
