CREATE TABLE "public"."group_invites" (
  "created_at" timestamp(6) DEFAULT (now()) NOT NULL,
  "group_id" int4 NOT NULL,
  "id" SERIAL NOT NULL,
  "invitee_id" int4 NOT NULL,
  "inviter_id" int4 NOT NULL,
  "message" text,
  "status" text DEFAULT 'pending' NOT NULL,
  PRIMARY KEY ("id")
