);
CREATE TABLE "public"."likes" (
  "created_at" timestamp(6) DEFAULT (now()) NOT NULL,
  "id" SERIAL NOT NULL,
  "post_id" int4 NOT NULL,
  "user_id" int4 NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE "public"."messages" (
  "content" text NOT NULL,
  "created_at" timestamp(6) DEFAULT (now()) NOT NULL,
  "id" SERIAL NOT NULL,
  "image_url" text,
  "receiver_id" int4 NOT NULL,
